/// Minimal re-implementation of `indicators::ProgressBar` string rendering.
///
/// The bar is rendered as:
/// `'['` + `'='` for each filled cell + `'>'` at the current position
/// (when progress < total) + spaces to pad to `width` + `']'` + `' '`
/// + percentage with one decimal + `'%'`.
///
/// All math uses `f32` to match C++ `float` semantics.
pub struct ProgressBar {
    progress: u32,
    total: u32,
    width: u32,
}

impl ProgressBar {
    pub fn new() -> Self {
        ProgressBar {
            progress: 0,
            total: 100,
            width: 70,
        }
    }

    pub fn set_progress(&mut self, progress: u32) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: u32) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: u32) {
        self.width = width;
    }

    pub fn str(&self) -> String {
        let fraction = self.progress as f32 / self.total as f32;
        // Truncating float->int cast, as in C++: pos = width * fraction
        let pos = (fraction * self.width as f32) as usize;
        let width = self.width as usize;

        let mut bar = String::with_capacity(width + 2);
        bar.push('[');
        for i in 0..width {
            if i < pos {
                bar.push('=');
            } else if i == pos && self.progress < self.total {
                bar.push('>');
            } else {
                bar.push(' ');
            }
        }
        bar.push(']');

        format!("{} {:.1}%", bar, fraction * 100.0f32)
    }
}

/// Minimal re-implementation of `indicators::Percentage` string rendering.
///
/// Formats `value * 100` with one decimal followed by `'%'`.
/// Uses `f32` to match C++ `float` semantics (e.g. `Percentage(0.75f)`).
pub struct Percentage(f32);

impl Percentage {
    pub fn new(value: f32) -> Self {
        Percentage(value)
    }

    pub fn str(&self) -> String {
        format!("{:.1}%", self.0 * 100.0f32)
    }
}

