// via `rustc test2.rs` run from this directory, thanks to the `#[path]`
// module declarations below.

#[path = "src/progress_bar.rs"]
mod progress_bar;
#[path = "src/percentage.rs"]
mod percentage;

use percentage::Percentage;
use progress_bar::ProgressBar;

fn main() {
    // Collected to mirror the C++ program's (unused) argc/argv; ignored.
    let _args: Vec<String> = std::env::args().collect();

    let mut bar = ProgressBar::new();
    bar.set_progress(75);
    bar.set_total(100);
    bar.set_width(30);
    println!("{}", bar.str());

    let pct = Percentage::new(0.75f32);
    println!("{}", pct.str());
}
